def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    colors = {x for row in grid for x in row if x != bg}

    # Find the long straight marker color, then recolor the nearest other object.
    marker = None
    best = 0
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        rows = {}
        cols = {}
        for r, c in cells:
            rows[r] = rows.get(r, 0) + 1
            cols[c] = cols.get(c, 0) + 1
        score = max(max(rows.values(), default=0), max(cols.values(), default=0))
        if score > best:
            best, marker = score, color

    if marker is None:
        return [row[:] for row in grid]

    marker_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    candidates = []
    for color in colors - {marker}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        dist = min(abs(r-a) + abs(c-b) for r, c in cells for a, b in marker_cells)
        candidates.append((dist, color))
    if not candidates:
        return [row[:] for row in grid]
    target = min(candidates)[1]
    return [[marker if x == target else x for x in row] for row in grid]
